<script setup lang="ts">
import{computed,ref}from'vue';
import{parityMessages}from'./parity-labels';
import{localizedMessages}from'../../../packages/locales';
import{defaultVectorPath,supportsVectorPath,vectorPathData}from'../../../packages/comp-bridge/layer-styles.mjs';
import type{Language,ViewerProject,LayerRow,OpenResult}from'./types';
const props=defineProps<{language:Language;project:ViewerProject;layer?:LayerRow;editing:boolean;mode:'path'|'mask';commit:(op:Record<string,unknown>,owner:{id:string;revision:string})=>Promise<OpenResult>}>();
const emit=defineEmits(['close']);
const owner={id:props.project.id,revision:props.project.revision},existing=props.editing?props.layer:undefined;
const initial=props.mode==='mask'?existing?.vectorMask:existing?.shape?.vector;
const vector=ref<any>(JSON.parse(JSON.stringify(initial??defaultVectorPath()))),color=ref('#000000'),contour=ref(0),selected=ref(-1),drawing=ref(!initial),busy=ref(false),error=ref(''),svg=ref<SVGSVGElement>(),space=ref(false);
const size=props.mode==='mask'?existing?.maskPixelSize??props.layer?.pixelSize:existing?.pixelSize;
const[width,height]=size??[props.project.manifest.width,props.project.manifest.height],view=ref({x:0,y:0,w:width,h:height});
const t=computed(()=>parityMessages[props.language]),anchor=computed(()=>vector.value.contours[contour.value]?.anchors[selected.value]);
const contours=computed<any[]>(()=>vector.value.contours),activeAnchors=computed<any[]>(()=>contours.value[contour.value]?.anchors??[]);
if(existing?.shape)color.value='#'+['red','green','blue'].map(key=>Math.round(Number(existing.shape![key]??0)*255).toString(16).padStart(2,'0')).join('');
const cleaned=computed(()=>({...vector.value,contours:vector.value.contours.filter((value:any)=>value.anchors.length)}));
const valid=computed(()=>supportsVectorPath(cleaned.value));
const path=computed(()=>cleaned.value.contours.length?vectorPathData(cleaned.value.contours,width,height):'');
const radius=computed(()=>Math.max(view.value.w,view.value.h)/100);
const groups=computed(()=>{const result:{color:string;contours:any[]}[]=[];for(const entry of cleaned.value.contours){const paint=props.mode==='mask'?'#ffffff':entry.color?'#'+['red','green','blue'].map(key=>Math.round(entry.color[key]*255).toString(16).padStart(2,'0')).join(''):color.value;if(result.at(-1)?.color===paint)result.at(-1)!.contours.push(entry);else result.push({color:paint,contours:[entry]});}return result;});
const handles=computed(()=>anchor.value?['incoming','outgoing'].filter(key=>anchor.value[key]):[]);
const stroke=computed(()=>'#'+['red','green','blue'].map(key=>Math.round(vector.value.strokeColor[key]*255).toString(16).padStart(2,'0')).join(''));
let drag:any;
function point(event:PointerEvent|WheelEvent){const matrix=svg.value?.getScreenCTM();if(!matrix)return[0,0];const p=new DOMPoint(event.clientX,event.clientY).matrixTransform(matrix.inverse());return[p.x/width,p.y/height];}
function capture(event:PointerEvent){svg.value?.setPointerCapture(event.pointerId);svg.value?.focus();}
function start(event:PointerEvent){if(busy.value||event.button!==0)return;const p=point(event);capture(event);if(space.value){drag={type:'pan',x:event.clientX,y:event.clientY,view:{...view.value}};return;}if(!drawing.value)return;const entry=vector.value.contours[contour.value],last=entry.anchors.at(-1);if(last&&Math.hypot((last.point[0]-p[0])*width,(last.point[1]-p[1])*height)<radius.value)return;entry.anchors.push({point:p,smooth:false});selected.value=entry.anchors.length-1;drag={type:'new'};}
function node(event:PointerEvent,index:number){if(busy.value||event.button!==0)return;if(drawing.value&&index===0&&vector.value.contours[contour.value].anchors.length>1){vector.value.contours[contour.value].closed=true;drawing.value=false;selected.value=0;return;}selected.value=index;capture(event);if(event.altKey){removeHandles();return;}drag={type:'point',start:point(event),before:JSON.parse(JSON.stringify(anchor.value))};}
function handle(event:PointerEvent,key:string){if(busy.value)return;capture(event);if(event.altKey)anchor.value.smooth=false;drag={type:key};}
function move(event:PointerEvent){if(!drag||busy.value)return;if(drag.type==='pan'){const bounds=svg.value!.getBoundingClientRect();view.value={...drag.view,x:drag.view.x-(event.clientX-drag.x)*drag.view.w/bounds.width,y:drag.view.y-(event.clientY-drag.y)*drag.view.h/bounds.height};return;}if(!anchor.value)return;const p=point(event);if(drag.type==='point'){const delta=[p[0]-drag.start[0],p[1]-drag.start[1]];for(const key of ['point','incoming','outgoing'])if(drag.before[key])anchor.value[key]=drag.before[key].map((v:number,index:number)=>v+delta[index]);}
  else{const key=drag.type==='new'?'outgoing':drag.type;anchor.value[key]=p;if(drag.type==='new')anchor.value.smooth=true;if(anchor.value.smooth&&!event.altKey){const opposite=key==='outgoing'?'incoming':'outgoing';anchor.value[opposite]=anchor.value.point.map((v:number,index:number)=>2*v-p[index]);}}}
function end(){drag=undefined;}
function newContour(){if(!vector.value.contours[contour.value].anchors.length)return;vector.value.contours.push({anchors:[],closed:false});contour.value=vector.value.contours.length-1;selected.value=-1;drawing.value=true;}
function removeAnchor(){if(selected.value<0)return;vector.value.contours[contour.value].anchors.splice(selected.value,1);selected.value=Math.min(selected.value,vector.value.contours[contour.value].anchors.length-1);}
function removeHandles(){if(!anchor.value)return;delete anchor.value.incoming;delete anchor.value.outgoing;anchor.value.smooth=false;}
function wheel(event:WheelEvent){if(drag||busy.value)return;const p=point(event),factor=event.deltaY>0?1.2:1/1.2,w=Math.min(width*10,Math.max(width/100,view.value.w*factor)),h=w*height/width,px=p[0]*width,py=p[1]*height;view.value={x:px-(px-view.value.x)*w/view.value.w,y:py-(py-view.value.y)*h/view.value.h,w,h};}
function key(event:KeyboardEvent){if(event.isComposing)return;if(event.key==='Escape'){event.preventDefault();event.stopPropagation();if(!busy.value)emit('close');return;}if((event.target as HTMLElement).closest('input,select,textarea,button,[contenteditable]'))return;if(event.key===' '){space.value=true;event.preventDefault();return;}if(event.key==='Delete'||event.key==='Backspace'){removeAnchor();event.preventDefault();}if(event.key==='Enter'){event.preventDefault();if(valid.value&&!busy.value)void apply();}if(anchor.value&&['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(event.key)){const delta=(event.shiftKey?10:1),axis=['ArrowLeft','ArrowRight'].includes(event.key)?0:1,amount=delta*(event.key==='ArrowLeft'||event.key==='ArrowUp'?-1:1)/(axis?height:width);for(const name of ['point','incoming','outgoing'])if(anchor.value[name])anchor.value[name][axis]+=amount;event.preventDefault();}}
async function apply(){if(!valid.value)return;busy.value=true;error.value='';try{const rgb=Object.fromEntries(['red','green','blue'].map((name,index)=>[name,parseInt(color.value.slice(index*2+1,index*2+3),16)/255]));const result=await props.commit({kind:props.mode==='mask'?'vectorMask':'path',id:existing?.id??(props.mode==='mask'?props.layer?.id:undefined),style:JSON.parse(JSON.stringify(cleaned.value)),color:rgb,name:t.value.path,...(!existing&&props.mode==='path'&&props.layer?{parentID:props.layer.isGroup?props.layer.id:props.layer.parentID}:{})},owner);if(result.project)emit('close');else if(result.error)error.value=result.error==='locked'?t.value.locked:(localizedMessages(props.language,'windows').errors as Record<string,string>)[result.error]??t.value.failed;}catch{error.value=t.value.failed;}finally{busy.value=false;}}
</script>
<template><div class="modal-shade" @click.self="!busy&&emit('close')"><section class="dialog path-dialog" role="dialog" aria-modal="true" :aria-label="mode==='mask'?t.vectorMask:t.path" @keydown="key" @keyup.space="space=false"><h2>{{mode==='mask'?t.vectorMask:t.path}}</h2><p>{{t.pathTip}}</p><p v-if="error" role="alert">{{error}}</p>
  <div class="button-row"><button :disabled="busy" @click="drawing=!drawing">{{drawing?t.editMode:t.drawMode}}</button><button :disabled="busy" @click="newContour()">{{t.newContour}}</button><button :disabled="busy" @click="drawing=false">{{t.finishContour}}</button><button :disabled="busy||!vector.contours[contour].anchors.length" @click="vector.contours[contour].closed=true;drawing=false">{{t.closeContour}}</button><label>{{t.contours}}<select v-model.number="contour" :disabled="busy" @change="selected=-1"><option v-for="(_,index) in contours" :key="index" :value="index">{{index+1}}</option></select></label></div>
  <svg ref="svg" data-testid="path-editor" tabindex="0" class="path-editor" :viewBox="`${view.x} ${view.y} ${view.w} ${view.h}`" @pointerdown="start" @pointermove="move" @pointerup="end" @pointercancel="end" @dblclick.prevent="drawing=false" @wheel.prevent="wheel"><rect v-if="mode==='mask'" width="100%" height="100%" fill="black"/><image v-if="mode==='path'&&existing?.imageFile" :href="project.urls['images/'+existing.imageFile]" :width="width" :height="height" opacity=".25"/><path v-for="(group,index) in groups" v-show="mode==='mask'||vector.fillEnabled" :key="index" :d="vectorPathData(group.contours,width,height)" :fill="group.color" :fill-rule="vector.evenOdd?'evenodd':'nonzero'" pointer-events="none"/><path :d="path" fill="none" :stroke="mode==='mask'?'#ffffff':vector.strokeEnabled?stroke:'#b9e5d2'" :stroke-width="mode!=='mask'&&vector.strokeEnabled?vector.strokeWidth:radius/8" stroke-linejoin="round" :stroke-linecap="vector.roundCaps?'round':'butt'" pointer-events="none"/>
    <template v-if="anchor"><g v-for="name in handles" :key="name"><line :x1="anchor.point[0]*width" :y1="anchor.point[1]*height" :x2="anchor[name][0]*width" :y2="anchor[name][1]*height" stroke="#ffc86b" :stroke-width="radius/6"/><circle :cx="anchor[name][0]*width" :cy="anchor[name][1]*height" :r="radius*.6" fill="#ffc86b" @pointerdown.stop="handle($event,name)"/></g></template>
    <circle v-for="(entry,index) in activeAnchors" :key="index" :cx="entry.point[0]*width" :cy="entry.point[1]*height" :r="radius*.65" :fill="selected===index?'#b9e5d2':'#fff'" stroke="#18392b" :stroke-width="radius/5" @pointerdown.stop="node($event,index)"/>
  </svg>
  <div class="style-fields"><label><input v-model="vector.evenOdd" type="checkbox" :disabled="busy">{{t.evenOdd}}</label><label v-if="mode==='path'"><input v-model="vector.fillEnabled" type="checkbox" :disabled="busy">{{t.pathFill}}<input v-model="color" type="color" :disabled="busy"></label><label v-if="mode==='path'"><input v-model="vector.strokeEnabled" type="checkbox" :disabled="busy">{{t.pathStroke}}<input type="color" :value="stroke" :disabled="busy" @input="['red','green','blue'].forEach((name,index)=>vector.strokeColor[name]=parseInt(($event.target as HTMLInputElement).value.slice(index*2+1,index*2+3),16)/255)"></label><label v-if="mode==='path'">{{t.strokeWidth}}<input v-model.number="vector.strokeWidth" type="number" min="0" max="5000" :disabled="busy"></label><label v-if="mode==='path'"><input v-model="vector.roundCaps" type="checkbox" :disabled="busy">{{t.roundCaps}}</label></div>
  <div v-if="anchor" class="button-row"><label>X<input type="number" :value="anchor.point[0]*width" :disabled="busy" @change="anchor.point[0]=Number(($event.target as HTMLInputElement).value)/width"></label><label>Y<input type="number" :value="anchor.point[1]*height" :disabled="busy" @change="anchor.point[1]=Number(($event.target as HTMLInputElement).value)/height"></label><button :disabled="busy" @click="removeAnchor()">{{t.deleteAnchor}}</button><button :disabled="busy" @click="removeHandles()">{{t.removeHandles}}</button></div>
  <div class="button-row dialog-actions"><span>{{cleaned.contours.reduce((count:number,item:any)=>count+item.anchors.length,0)}} {{t.anchors}}</span><button :disabled="busy" @click="emit('close')">{{t.cancel}}</button><button class="primary" data-testid="apply-path" :disabled="busy||!valid" @click="apply()">{{busy?t.loading:t.apply}}</button></div>
</section></div></template>
<style scoped>.path-dialog{width:min(1000px,96vw);max-height:94vh;overflow:auto}.path-editor{width:100%;height:min(46vh,480px);display:block;touch-action:none;background:repeating-conic-gradient(#666 0 25%,#888 0 50%) 0/16px 16px;outline:1px solid var(--border);margin:12px 0}.path-editor:focus{outline:2px solid var(--accent)}.path-dialog label{display:inline-flex;align-items:center;gap:6px}.path-dialog input[type=number]{width:90px}</style>
